import React, { useState, useEffect } from 'react';
import { AlertTriangle, Upload } from 'lucide-react';
import api from '../services/api';

export default function ProfessorFaltas() {
  const [profDisciplinas, setProfDisciplinas] = useState([]);
  const [turmaAlunos, setTurmaAlunos] = useState([]);
  const [selectedTurma, setSelectedTurma] = useState('');
  const [selectedMatricula, setSelectedMatricula] = useState('');
  const [selectedDisciplina, setSelectedDisciplina] = useState('');
  const [dataFalta, setDataFalta] = useState('');
  const [justificativaFalta, setJustificativaFalta] = useState('');
  const [faltaSaving, setFaltaSaving] = useState(false);
  const [faltaMsg, setFaltaMsg] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get('/professor/minhas-disciplinas')
      .then(r => setProfDisciplinas(r.data || []))
      .catch(() => setProfDisciplinas([]))
      .finally(() => setLoading(false));
  }, []);

  const turmasUnicas = [...new Map(profDisciplinas.map(d => [d.turma_id, { id: d.turma_id, nome: d.turma_nome }])).values()];

  const abrirTurma = async (turmaId) => {
    setSelectedTurma(turmaId);
    setSelectedMatricula('');
    setTurmaAlunos([]);
    try {
      const r = await api.get(`/staff/turmas/${turmaId}/alunos`);
      setTurmaAlunos(r.data || []);
    } catch {
      setTurmaAlunos([]);
    }
  };

  const registarFalta = async () => {
    setFaltaMsg('');
    if (!selectedMatricula || !selectedDisciplina || !dataFalta) {
      setFaltaMsg('Preencha aluno, disciplina e data.');
      return;
    }
    setFaltaSaving(true);
    try {
      await api.post('/professor/faltas', {
        matricula_id: selectedMatricula,
        disciplina_id: selectedDisciplina,
        data_falta: dataFalta,
        justificativa: justificativaFalta,
      });
      setFaltaMsg('✓ Falta registada com sucesso!');
      setSelectedMatricula('');
      setJustificativaFalta('');
      setDataFalta('');
      setTimeout(() => setFaltaMsg(''), 3000);
    } catch (err) {
      setFaltaMsg(err.response?.data?.message || 'Erro ao registar falta.');
    } finally {
      setFaltaSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <div className="spinner" />
      </div>
    );
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <h2><AlertTriangle size={24} style={{ verticalAlign: 'middle', marginRight: 8 }} />Registar Faltas</h2>
        <p style={{ color: 'var(--cinza)' }}>Registe as faltas dos seus alunos por disciplina e turma.</p>
      </div>

      <div className="card">
        {turmasUnicas.length === 0 ? (
          <div className="empty-state">
            <AlertTriangle size={48} style={{ opacity: 0.3 }} />
            <h3>Sem turmas atribuídas</h3>
            <p>Não tem turmas/disciplinas atribuídas no momento.</p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
            {faltaMsg && (
              <div className={`alert ${faltaMsg.includes('✓') ? 'alert-success' : faltaMsg.includes('Erro') ? 'alert-error' : 'alert-info'}`}>
                {faltaMsg}
              </div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem' }}>
              {turmasUnicas.map(turma => (
                <button
                  key={turma.id}
                  className={`btn ${selectedTurma === turma.id ? 'btn-primary' : 'btn-outline'}`}
                  onClick={() => abrirTurma(turma.id)}
                  style={{ textAlign: 'left' }}
                >
                  {turma.nome}
                </button>
              ))}
            </div>

            {selectedTurma && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', borderTop: '1px solid var(--bege)', paddingTop: '1.5rem' }}>
                <h3 style={{ fontSize: '1rem', marginBottom: 0, color: 'var(--castanho-medio)' }}>Registar Falta</h3>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Aluno *</label>
                    <select
                      className="form-control form-select"
                      value={selectedMatricula}
                      onChange={e => setSelectedMatricula(e.target.value)}
                    >
                      <option value="">Selecione aluno</option>
                      {turmaAlunos.map(a => (
                        <option key={a.matricula_id} value={a.matricula_id}>
                          {a.aluno_nome}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div className="form-group">
                    <label className="form-label">Disciplina *</label>
                    <select
                      className="form-control form-select"
                      value={selectedDisciplina}
                      onChange={e => setSelectedDisciplina(e.target.value)}
                    >
                      <option value="">Selecione disciplina</option>
                      {profDisciplinas
                        .filter(d => String(d.turma_id) === String(selectedTurma))
                        .map(d => (
                          <option key={d.disciplina_id} value={d.disciplina_id}>
                            {d.disciplina_nome}
                          </option>
                        ))}
                    </select>
                  </div>
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Data da Falta *</label>
                    <input className="form-control" type="date" value={dataFalta} onChange={e => setDataFalta(e.target.value)} />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Justificativa (opcional)</label>
                    <input className="form-control" value={justificativaFalta} onChange={e => setJustificativaFalta(e.target.value)} />
                  </div>
                </div>

                <div style={{ display: 'flex', gap: 12 }}>
                  <button className="btn btn-primary" onClick={registarFalta} disabled={faltaSaving}>
                    <Upload size={16} /> {faltaSaving ? 'A guardar...' : 'Registar Falta'}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
